{"CodeContent": "package pre_oder

import (
	"backend/internal/app/entity"
	"time"
)

type PreOrderItemRequestDTO struct {
	ProductID uint    `json:"product_id" binding:"required"`
	Quantity  int     `json:"quantity" binding:"required,gt=0"`
	UnitPrice float64 `json:"unit_price" binding:"required,gt=0"`
}

type PreOrderRequestDTO struct {
	PreOrderType  string                   `json:"pre_order_type" binding:"required"`
	CustomerID    uint                     `json:"customer_id" binding:"required"`
	DepositAmount float64                  `json:"deposit_amount" binding:"min=0"`
	Status        string                   `json:"status" binding:"required"`
	SupplierID    uint                     `json:"supplier_id" binding:"required"`
	Items         []PreOrderItemRequestDTO `json:"items" binding:"required,dive"`
}

type PreOrderItemResponseDTO struct {
	ID          uint    `json:"id"`
	ProductID   uint    `json:"product_id"`
	ProductName string  `json:"product_name"`
	ProductCode string  `json:"product_code"`
	Quantity    int     `json:"quantity"`
	UnitPrice   float64 `json:"unit_price"`
	NetAmount   float64 `json:"net_amount"`
}

type PreOrderResponseDTO struct {
	ID            uint                      `json:"id"`
	PreOrderType  string                    `json:"pre_order_type"`
	CustomerID    uint                      `json:"customer_id"`
	CustomerName  string                    `json:"customer_name"`
	CustomerPhone string                    `json:"customer_phone"`
	DepositAmount float64                   `json:"deposit_amount"`
	Status        string                    `json:"status"`
	OrderDate     time.Time                 `json:"order_date"`
	SupplierID    uint                      `json:"supplier_id"`
	SupplierName  string                    `json:"supplier_name"`
	Items         []PreOrderItemResponseDTO `json:"items"`
	CreatedAt     time.Time                 `json:"created_at"`
	UpdatedAt     time.Time                 `json:"updated_at"`
}

func (dto *PreOrderRequestDTO) ToEntity() entity.PreOrder {
	var items []entity.PreOrderItem
	for _, item := range dto.Items {
		items = append(items, entity.PreOrderItem{
			ProductID: item.ProductID,
			Quantity:  item.Quantity,
			UnitPrice: item.UnitPrice,
		})
	}

	return entity.PreOrder{
		PreOrderType:  dto.PreOrderType,
		CustomerID:    dto.CustomerID,
		DepositAmount: dto.DepositAmount,
		Status:        dto.Status,
		OrderDate:     time.Now(),
		SupplierID:    dto.SupplierID,
		PreOrderItems: items,
	}
}

func FromEntity(po entity.PreOrder) PreOrderResponseDTO {
	var items []PreOrderItemResponseDTO
	for _, item := range po.PreOrderItems {
		prodName := ""
		prodCode := ""
		if item.Product != nil {
			prodName = item.Product.Product_Name
			prodCode = item.Product.Product_Code
		}

		items = append(items, PreOrderItemResponseDTO{
			ID:          item.ID,
			ProductID:   item.ProductID,
			ProductName: prodName,
			ProductCode: prodCode,
			Quantity:    item.Quantity,
			UnitPrice:   item.UnitPrice,
			NetAmount:   float64(item.Quantity) * item.UnitPrice,
		})
	}

	custName := ""
	custPhone := ""
	if po.Customer != nil {
		custName = po.Customer.Customer_Name
		custPhone = po.Customer.Customer_Phone
	}

	suppName := ""
	if po.Supplier != nil {
		suppName = po.Supplier.Supplier_Name
	}

	return PreOrderResponseDTO{
		ID:            po.ID,
		PreOrderType:  po.PreOrderType,
		CustomerID:    po.CustomerID,
		CustomerName:  custName,
		CustomerPhone: custPhone,
		DepositAmount: po.DepositAmount,
		Status:        po.Status,
		OrderDate:     po.OrderDate,
		SupplierID:    po.SupplierID,
		SupplierName:  suppName,
		Items:         items,
		CreatedAt:     po.CreatedAt,
		UpdatedAt:     po.UpdatedAt,
	}
}
