{"CodeContent": "package pre_oder

import (
	"backend/internal/app/entity"
	"gorm.io/gorm"
)

type PreOrderRepository interface {
	Create(po *entity.PreOrder) error
	GetByID(id uint) (*entity.PreOrder, error)
	List(status string) ([]entity.PreOrder, error)
	Update(po *entity.PreOrder) error
	Delete(id uint) error
}

type preOrderRepository struct {
	db *gorm.DB
}

func NewPreOrderRepository(db *gorm.DB) PreOrderRepository {
	return &preOrderRepository{db: db}
}

func (r *preOrderRepository) Create(po *entity.PreOrder) error {
	return r.db.Create(po).Error
}

func (r *preOrderRepository) GetByID(id uint) (*entity.PreOrder, error) {
	var po entity.PreOrder
	err := r.db.
		Preload("Customer").
		Preload("Supplier").
		Preload("PreOrderItems.Product").
		First(&po, id).Error
	if err != nil {
		return nil, err
	}
	return &po, nil
}

func (r *preOrderRepository) List(status string) ([]entity.PreOrder, error) {
	var list []entity.PreOrder
	query := r.db.
		Preload("Customer").
		Preload("Supplier").
		Preload("PreOrderItems.Product")

	if status != "" {
		query = query.Where("status = ?", status)
	}

	err := query.Order("created_at desc").Find(&list).Error
	return list, err
}

func (r *preOrderRepository) Update(po *entity.PreOrder) error {
	// Use transaction to update pre-order items correctly
	return r.db.Transaction(func(tx *gorm.DB) error {
		// 1. Delete existing items
		if err := tx.Where("pre_order_id = ?", po.ID).Delete(&entity.PreOrderItem{}).Error; err != nil {
			return err
		}

		// 2. Save parent pre-order details
		if err := tx.Session(&gorm.Session{FullSaveAssociations: true}).Save(po).Error; err != nil {
			return err
		}

		return nil
	})
}

func (r *preOrderRepository) Delete(id uint) error {
	return r.db.Transaction(func(tx *gorm.DB) error {
		// Delete items first
		if err := tx.Where("pre_order_id = ?", id).Delete(&entity.PreOrderItem{}).Error; err != nil {
			return err
		}
		// Delete parent pre-order
		if err := tx.Delete(&entity.PreOrder{}, id).Error; err != nil {
			return err
		}
		return nil
	})
}
