import (
	"backend/internal/app/entity"
	"errors"
)

type PreOrderService interface {
	CreatePreOrder(dto PreOrderRequestDTO) (*entity.PreOrder, error)
	GetPreOrder(id uint) (*entity.PreOrder, error)
	ListPreOrders(status string) ([]entity.PreOrder, error)
	UpdatePreOrder(id uint, dto PreOrderRequestDTO) (*entity.PreOrder, error)
	DeletePreOrder(id uint) error
}

type preOrderService struct {
	repo PreOrderRepository
}

func NewPreOrderService(repo PreOrderRepository) PreOrderService {
	return &preOrderService{repo: repo}
}

func (s *preOrderService) CreatePreOrder(dto PreOrderRequestDTO) (*entity.PreOrder, error) {
	po := dto.ToEntity()
	if err := s.repo.Create(&po); err != nil {
		return nil, err
	}
	// Retrieve fully loaded object with preloads
	return s.repo.GetByID(po.ID)
}

func (s *preOrderService) GetPreOrder(id uint) (*entity.PreOrder, error) {
	return s.repo.GetByID(id)
}

func (s *preOrderService) ListPreOrders(status string) ([]entity.PreOrder, error) {
	return s.repo.List(status)
}

func (s *preOrderService) UpdatePreOrder(id uint, dto PreOrderRequestDTO) (*entity.PreOrder, error) {
	existing, err := s.repo.GetByID(id)
	if err != nil {
		return nil, err
	}
	if existing == nil {
		return nil, errors.New("pre-order not found")
	}

	// Update fields
	existing.PreOrderType = dto.PreOrderType
	existing.CustomerID = dto.CustomerID
	existing.DepositAmount = dto.DepositAmount
	existing.Status = dto.Status
	existing.SupplierID = dto.SupplierID

	// Map and update items
	var newItems []entity.PreOrderItem
	for _, item := range dto.Items {
		newItems = append(newItems, entity.PreOrderItem{
			PreOrderID: id,
			ProductID:  item.ProductID,
			Quantity:   item.Quantity,
			UnitPrice:  item.UnitPrice,
		})
	}
	existing.PreOrderItems = newItems

	if err := s.repo.Update(existing); err != nil {
		return nil, err
	}

	return s.repo.GetByID(id)
}

func (s *preOrderService) DeletePreOrder(id uint) error {
	return s.repo.Delete(id)
}
