	po, err := ctrl.service.GetPreOrder(uint(id))
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
		return
	}
	if po == nil {
		c.JSON(http.StatusNotFound, gin.H{"error": "pre-order not found"})
		return
	}

	c.JSON(http.StatusOK, pre_oder.FromEntity(*po))
}

