	status := c.Query("status")

	list, err := ctrl.service.ListPreOrders(status)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
		return
	}

	var response []pre_oder.PreOrderResponseDTO
	for _, po := range list {
		response = append(response, pre_oder.FromEntity(po))
	}

	c.JSON(http.StatusOK, response)
}

