{"CodeContent": "import React, { useState, useEffect } from 'react';
import apiClient from '../../../service/http/apiClient';
import { 
  Plus, Search, Edit, Trash2, ChevronLeft, Save, 
  Package, Calendar, DollarSign, User, FileText, 
  CheckCircle, Clock, XCircle, Loader2, AlertCircle
} from 'lucide-react';
import { 
  getPreOrders, getPreOrderById, createPreOrder, 
  updatePreOrder, deletePreOrder 
} from '../../../service/http/pre-order';
import { PreOrder, PreOrderItem } from '../../../interface/pre-order';

interface Customer {
  id: number;
  customer_name: string;
  customer_phone: string;
}

interface Supplier {
  id: number;
  supplier_name: string;
}

interface Product {
  id: number;
  product_name: string;
  product_code: string;
  sale_price: number;
}

export default function PreOrderManager() {
  const [preOrders, setPreOrders] = useState<PreOrder[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [products, setProducts] = useState<Product[]>([]);

  // UI Views & states
  const [view, setView] = useState<'list' | 'form'>('list');
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('');
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  // Form state
  const [editingId, setEditingId] = useState<number | null>(null);
  const [formType, setFormType] = useState<string>('WALK_IN');
  const [formCustomerId, setFormCustomerId] = useState<number>(0);
  const [formSupplierId, setFormSupplierId] = useState<number>(0);
  const [formDepositAmount, setFormDepositAmount] = useState<number>(0);
  const [formStatus, setFormStatus] = useState<string>('PENDING');
  const [formItems, setFormItems] = useState<PreOrderItem[]>([]);

  // Fetch initial data
  useEffect(() => {
    fetchPreOrders();
    fetchSupportData();
  }, []);

  const fetchPreOrders = async () => {
    setLoading(true);
    setErrorMsg(null);
    try {
      const data = await getPreOrders(statusFilter || undefined);
      setPreOrders(data || []);
    } catch (err: any) {
      console.error('Error fetching pre-orders:', err);
      setErrorMsg('ล้มเหลวในการโหลดรายการจองล่วงหน้า');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchPreOrders();
  }, [statusFilter]);

  const fetchSupportData = async () => {
    try {
      const [custRes, suppRes, prodRes] = await Promise.all([
        apiClient.get('/wms/customers'),
        apiClient.get('/wms/suppliers'),
        apiClient.get('/wms/products'),
      ]);

      setCustomers(Array.isArray(custRes.data) ? custRes.data : (custRes.data.data || []));
      setSuppliers(Array.isArray(suppRes.data) ? suppRes.data : (suppRes.data.data || []));
      setProducts(Array.isArray(prodRes.data) ? prodRes.data : (prodRes.data.data || []));
    } catch (err) {
      console.error('Error fetching dropdown helper data:', err);
    }
  };

  const handleCreateNew = () => {
    setEditingId(null);
    setFormType('WALK_IN');
    setFormCustomerId(customers[0]?.id || 0);
    setFormSupplierId(suppliers[0]?.id || 0);
    setFormDepositAmount(0);
    setFormStatus('PENDING');
    setFormItems([]);
    setView('form');
    setErrorMsg(null);
  };

  const handleEdit = async (id: number) => {
    setLoading(true);
    setErrorMsg(null);
    try {
      const data = await getPreOrderById(id);
      if (data) {
        setEditingId(id);
        setFormType(data.pre_order_type);
        setFormCustomerId(data.customer_id);
        setFormSupplierId(data.supplier_id);
        setFormDepositAmount(data.deposit_amount);
        setFormStatus(data.status);
        setFormItems(data.items || []);
        setView('form');
      }
    } catch (err: any) {
      console.error('Error fetching pre-order detail:', err);
      setErrorMsg('ไม่สามารถดึงข้อมูลรายละเอียดรายการจองนี้ได้');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: number) => {
    if (!window.confirm('คุณแน่ใจหรือไม่ว่าต้องการลบรายการสั่งจองนี้?')) return;
    try {
      await deletePreOrder(id);
      setPreOrders(prev => prev.filter(po => po.id !== id));
    } catch (err) {
      console.error('Error deleting pre-order:', err);
      alert('ล้มเหลวในการลบรายการสั่งจอง');
    }
  };

  const handleAddItem = () => {
    if (products.length === 0) return;
    const defaultProduct = products[0];
    const newItem: PreOrderItem = {
      product_id: defaultProduct.id,
      quantity: 1,
      unit_price: defaultProduct.sale_price || 0
    };
    setFormItems(prev => [...prev, newItem]);
  };

  const handleRemoveItem = (index: number) => {
    setFormItems(prev => prev.filter((_, idx) => idx !== index));
  };

  const handleItemChange = (index: number, field: keyof PreOrderItem, value: any) => {
    setFormItems(prev => {
      const updated = [...prev];
      if (field === 'product_id') {
        const prod = products.find(p => p.id === Number(value));
        updated[index] = {
          ...updated[index],
          product_id: Number(value),
          unit_price: prod ? prod.sale_price : updated[index].unit_price
        };
      } else if (field === 'quantity') {
        updated[index] = { ...updated[index], quantity: Number(value) || 1 };
      } else if (field === 'unit_price') {
        updated[index] = { ...updated[index], unit_price: Number(value) || 0 };
      }
      return updated;
    });
  };

  const calculateTotal = () => {
    return formItems.reduce((sum, item) => sum + (item.quantity * item.unit_price), 0);
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (formCustomerId === 0) {
      setErrorMsg('กรุณาเลือกข้อมูลลูกค้า');
      return;
    }
    if (formSupplierId === 0) {
      setErrorMsg('กรุณาเลือกผู้ผลิต/ซัพพลายเออร์');
      return;
    }
    if (formItems.length === 0) {
      setErrorMsg('กรุณาเพิ่มรายการสินค้าอย่างน้อย 1 รายการ');
      return;
    }

    setSaving(true);
    setErrorMsg(null);

    const payload: PreOrder = {
      pre_order_type: formType,
      customer_id: formCustomerId,
      deposit_amount: formDepositAmount,
      status: formStatus,
      supplier_id: formSupplierId,
      items: formItems
    };

    try {
      if (editingId) {
        await updatePreOrder(editingId, payload);
      } else {
        await createPreOrder(payload);
      }
      await fetchPreOrders();
      setView('list');
    } catch (err: any) {
      console.error('Error saving pre-order:', err);
      setErrorMsg(err.response?.data?.error || 'เกิดข้อผิดพลาดในการบันทึกข้อมูลใบจอง');
    } finally {
      setSaving(false);
    }
  };

  const filteredOrders = preOrders.filter(po => {
    const custName = po.customer_name?.toLowerCase() || '';
    const phone = po.customer_phone || '';
    const q = searchQuery.toLowerCase();
    return custName.includes(q) || phone.includes(q) || String(po.id).includes(q);
  });

  return (
    <div className="p-8 max-w-7xl mx-auto w-full font-sans">
      {view === 'list' ? (
        <div className="space-y-6">
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 border-b border-gray-200 pb-5">
            <div>
              <h1 className="text-3xl font-extrabold text-gray-900 tracking-tight flex items-center gap-3">
                <Package className="text-[#b32025]" size={36} />
                ระบบจัดการสั่งจองสินค้าล่วงหน้า (Pre-Orders)
              </h1>
              <p className="text-sm text-gray-500 mt-1">บันทึก ติดตามสถานะสินค้าจองมัดจำอะไหล่ด่วนสำหรับลูกค้าและช่าง</p>
            </div>
            <button 
              onClick={handleCreateNew}
              className="bg-[#b32025] hover:bg-[#961a1e] text-white font-bold py-2.5 px-6 rounded-lg shadow transition-all duration-150 flex items-center gap-2"
            >
              <Plus size={20} />
              สร้างใบสั่งจองใหม่
            </button>
          </div>

          {/* Filters & Search */}
          <div className="flex flex-col md:flex-row gap-4 bg-white p-4 rounded-xl border border-gray-100 shadow-sm">
            <div className="flex-1 relative">
              <Search className="absolute left-3.5 top-3.5 text-gray-400" size={18} />
              <input
                type="text"
                placeholder="ค้นหาชื่อลูกค้า, เบอร์โทรศัพท์ หรือเลขที่ใบสั่งจอง..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-10 pr-4 py-2.5 border border-gray-200 rounded-lg focus:ring-2 focus:ring-[#b32025]/20 focus:border-[#b32025] transition-all"
              />
            </div>
            <div className="flex gap-2 shrink-0">
              {['', 'PENDING', 'COMPLETED', 'CANCELLED'].map((status) => (
                <button
                  key={status}
                  onClick={() => setStatusFilter(status)}
                  className={`px-4 py-2.5 rounded-lg text-xs font-bold transition-all border ${
                    statusFilter === status 
                      ? 'bg-red-50 text-[#b32025] border-[#b32025]' 
                      : 'bg-gray-50 text-gray-600 border-gray-200 hover:bg-gray-100'
                  }`}
                >
                  {status === '' ? 'ทั้งหมด' : status === 'PENDING' ? 'ค้างส่งสินค้า/กำลังรอ' : status === 'COMPLETED' ? 'ส่งมอบสำเร็จ' : 'ยกเลิกรายการ'}
                </button>
              ))}
            </div>
          </div>

          {/* Loading view */}
          {loading ? (
            <div className="flex flex-col items-center justify-center p-12 bg-white rounded-xl border border-gray-100 shadow-sm min-h-[300px]">
              <Loader2 className="animate-spin text-[#b32025] mb-3" size={40} />
              <span className="text-gray-500 font-medium">กำลังโหลดข้อมูลรายการจอง...</span>
            </div>
          ) : filteredOrders.length === 0 ? (
            <div className="flex flex-col items-center justify-center p-12 bg-white rounded-xl border border-gray-100 shadow-sm min-h-[300px] text-gray-400">
              <FileText size={48} className="mb-3 text-gray-300" />
              <span className="font-semibold text-lg text-gray-600">ไม่พบข้อมูลรายการจองล่วงหน้า</span>
              <p className="text-xs text-gray-400 mt-1">ลองเปลี่ยนคำค้นหา หรือกดปุ่มบวกเพื่อเพิ่มใบสั่งจองใหม่</p>
            </div>
          ) : (
            <div className="bg-white rounded-xl border border-gray-100 shadow-sm overflow-hidden">
              <table className="w-full text-left text-sm">
                <thead className="bg-gray-50/50 border-b border-gray-100 text-xs text-gray-500 uppercase font-bold">
                  <tr>
                    <th className="py-4 px-6">เลขที่ใบจอง</th>
                    <th className="py-4 px-6">วันที่จอง</th>
                    <th className="py-4 px-6">ชื่อลูกค้า</th>
                    <th className="py-4 px-6">ช่องทางการสั่ง</th>
                    <th className="py-4 px-6">เงินมัดจำ</th>
                    <th className="py-4 px-6">สถานะ</th>
                    <th className="py-4 px-6 text-center">จัดการ</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100 text-gray-700">
                  {filteredOrders.map((po) => (
                    <tr key={po.id} className="hover:bg-gray-50/50 transition-colors">
                      <td className="py-4 px-6 font-mono font-bold text-[#b32025]">
                        PRE-{String(po.id).padStart(5, '0')}
                      </td>
                      <td className="py-4 px-6 font-medium text-gray-500 text-xs">
                        {po.order_date ? new Date(po.order_date).toLocaleDateString('th-TH', {
                          year: 'numeric', month: 'long', day: 'numeric',
                          hour: '2-digit', minute: '2-digit'
                        }) : '-'}
                      </td>
                      <td className="py-4 px-6">
                        <div className="font-bold text-gray-900">{po.customer_name}</div>
                        <div className="text-xs text-gray-400">{po.customer_phone}</div>
                      </td>
                      <td className="py-4 px-6 font-semibold">
                        <span className="text-xs bg-gray-100 px-2.5 py-1 rounded-md text-gray-600">
                          {po.pre_order_type === 'WALK_IN' ? 'หน้าร้าน' : po.pre_order_type === 'LINE' ? 'LINE OA' : 'เบอร์โทรศัพท์'}
                        </span>
                      </td>
                      <td className="py-4 px-6 font-bold text-emerald-600">
                        ฿{po.deposit_amount.toLocaleString()}
                      </td>
                      <td className="py-4 px-6">
                        <span className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold ${
                          po.status === 'COMPLETED' 
                            ? 'bg-emerald-50 text-emerald-600' 
                            : po.status === 'CANCELLED' 
                              ? 'bg-red-50 text-red-600' 
                              : 'bg-amber-50 text-amber-600'
                        }`}>
                          {po.status === 'COMPLETED' ? (
                            <CheckCircle size={14} />
                          ) : po.status === 'CANCELLED' ? (
                            <XCircle size={14} />
                          ) : (
                            <Clock size={14} />
                          )}
                          {po.status === 'COMPLETED' ? 'ส่งมอบแล้ว' : po.status === 'CANCELLED' ? 'ยกเลิก' : 'กำลังจัดหาอะไหล่'}
                        </span>
                      </td>
                      <td className="py-4 px-6">
                        <div className="flex justify-center gap-2">
                          <button 
                            onClick={() => handleEdit(po.id!)}
                            className="p-1.5 hover:bg-gray-100 rounded text-gray-600 transition-colors"
                            title="แก้ไข"
                          >
                            <Edit size={16} />
                          </button>
                          <button 
                            onClick={() => handleDelete(po.id!)}
                            className="p-1.5 hover:bg-red-50 rounded text-red-600 transition-colors"
                            title="ลบ"
                          >
                            <Trash2 size={16} />
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      ) : (
        <form onSubmit={handleSave} className="space-y-6">
          <div className="flex items-center justify-between border-b border-gray-200 pb-5">
            <div className="flex items-center gap-3">
              <button 
                type="button"
                onClick={() => setView('list')} 
                className="p-2 hover:bg-gray-100 rounded-full transition-colors"
              >
                <ChevronLeft size={24} className="text-gray-600" />
              </button>
              <div>
                <h1 className="text-2xl font-extrabold text-gray-900">
                  {editingId ? 'แก้ไขใบสั่งจองสินค้าล่วงหน้า' : 'สร้างใบสั่งจองสินค้าล่วงหน้า'}
                </h1>
                <p className="text-xs text-gray-400 mt-1">กรอกรายละเอียดลูกค้า อะไหล่ที่สั่งจอง และข้อมูลวางมัดจำ</p>
              </div>
            </div>
            <div className="flex gap-2">
              <button
                type="button"
                onClick={() => setView('list')}
                className="bg-white border border-gray-200 hover:bg-gray-50 text-gray-700 font-bold py-2.5 px-6 rounded-lg transition-all duration-150 text-sm"
              >
                ยกเลิก
              </button>
              <button
                type="submit"
                disabled={saving}
                className="bg-[#b32025] hover:bg-[#961a1e] text-white font-bold py-2.5 px-6 rounded-lg shadow transition-all duration-150 flex items-center gap-2 text-sm disabled:opacity-50"
              >
                {saving ? (
                  <Loader2 className="animate-spin" size={18} />
                ) : (
                  <Save size={18} />
                )}
                บันทึกใบสั่งจอง
              </button>
            </div>
          </div>

          {errorMsg && (
            <div className="p-4 bg-red-50 border border-red-200 text-red-700 text-sm rounded-lg flex items-center gap-3">
              <AlertCircle size={20} className="shrink-0 text-red-500" />
              <span>{errorMsg}</span>
            </div>
          )}

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            {/* Left/Middle: Info & Form Inputs */}
            <div className="lg:col-span-2 space-y-6">
              <div className="bg-white rounded-xl border border-gray-100 p-6 shadow-sm space-y-6">
                <h3 className="font-extrabold text-lg text-gray-900 border-b border-gray-100 pb-3">ข้อมูลการสั่งจอง</h3>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-xs font-bold text-gray-500 mb-2">ช่องทางการจอง</label>
                    <select
                      value={formType}
                      onChange={(e) => setFormType(e.target.value)}
                      className="w-full border border-gray-200 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-[#b32025]/20 focus:border-[#b32025] transition-all"
                    >
                      <option value="WALK_IN">หน้าร้าน (Walk-in)</option>
                      <option value="LINE">LINE OA</option>
                      <option value="TEL">โทรศัพท์</option>
                    </select>
                  </div>

                  <div>
                    <label className="block text-xs font-bold text-gray-500 mb-2">ลูกค้าในระบบ</label>
                    <select
                      value={formCustomerId}
                      onChange={(e) => setFormCustomerId(Number(e.target.value))}
                      className="w-full border border-gray-200 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-[#b32025]/20 focus:border-[#b32025] transition-all"
                    >
                      <option value={0}>-- เลือกข้อมูลลูกค้า --</option>
                      {customers.map(c => (
                        <option key={c.id} value={c.id}>{c.customer_name} ({c.customer_phone})</option>
                      ))}
                    </select>
                  </div>

                  <div>
                    <label className="block text-xs font-bold text-gray-500 mb-2">สั่งจองกับผู้ผลิต / ซัพพลายเออร์</label>
                    <select
                      value={formSupplierId}
                      onChange={(e) => setFormSupplierId(Number(e.target.value))}
                      className="w-full border border-gray-200 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-[#b32025]/20 focus:border-[#b32025] transition-all"
                    >
                      <option value={0}>-- เลือกซัพพลายเออร์ --</option>
                      {suppliers.map(s => (
                        <option key={s.id} value={s.id}>{s.supplier_name}</option>
                      ))}
                    </select>
                  </div>

                  <div>
