import json
import re

def extract_user_request(content):
    if not content:
        return ""
    # Extract content between <USER_REQUEST> and </USER_REQUEST>
    match = re.search(r'<USER_REQUEST>(.*?)</USER_REQUEST>', content, re.DOTALL)
    if match:
        return match.group(1).strip()
    return content.strip()

def clean_args(args):
    """Clean quotes from arguments returned in JSONL"""
    cleaned = {}
    for k, v in args.items():
        if isinstance(v, str):
            # Remove leading/trailing quotes if double serialized
            if v.startswith('"') and v.endswith('"'):
                v = v[1:-1]
        cleaned[k] = v
    return cleaned

def main():
    transcript_path = "/Users/phonsirithabunsri/.gemini/antigravity-cli/brain/9886e02d-2736-4e97-8bb3-121ab47042e8/.system_generated/logs/transcript_full.jsonl"
    workspace_dir = "/Users/phonsirithabunsri/Desktop/AutoParts-Retail-Management-Web-Application"

    chat_output_path = os.path.join(workspace_dir, "dataset_multiturn.json")
    trajectory_output_path = os.path.join(workspace_dir, "dataset_agent_trajectory.json")

    if not os.path.exists(transcript_path):
        transcript_path = "/Users/phonsirithabunsri/.gemini/antigravity-cli/brain/9886e02d-2736-4e97-8bb3-121ab47042e8/.system_generated/logs/transcript.jsonl"

    print(f"Reading logs from: {transcript_path}")

    chat_messages = []
    trajectory_messages = []

    # Track the active tool calls to match with tool response steps
    active_tool_calls = []

    with open(transcript_path, 'r', encoding='utf-8') as f:
        for line in f:
            try:
                data = json.loads(line.strip())
                step_index = data.get("step_index")
                step_type = data.get("type")
                source = data.get("source")
                content = data.get("content", "")

                # 1. USER INPUTS
                if step_type == "USER_INPUT" or source == "USER_EXPLICIT":
                    user_req = extract_user_request(content)
                    if user_req:
                        chat_messages.append({
                            "role": "user",
                            "content": user_req
                        })
                        trajectory_messages.append({
                            "role": "user",
                            "content": user_req
                        })

                # 2. MODEL PLANNER RESPONSES (Tool Calls or Final Responses)
                elif step_type == "PLANNER_RESPONSE" or source == "MODEL":
                    tool_calls_data = data.get("tool_calls", [])
                    thinking = data.get("thinking", "").strip()

                    if tool_calls_data:
                        # Convert to standard tool call objects
                        formatted_tool_calls = []
                        active_tool_calls = []

                        for i, tc in enumerate(tool_calls_data):
                            tool_name = tc.get("name")
                            tool_args = tc.get("args", {})
                            call_id = f"call_{step_index}_{i}"

                            formatted_call = {
                                "id": call_id,
                                "type": "function",
                                "function": {
                                    "name": tool_name,
                                    "arguments": json.dumps(clean_args(tool_args), ensure_ascii=False)
                                }
                            }
                            formatted_tool_calls.append(formatted_call)

                            # Keep track to pair with next environment response
                            active_tool_calls.append({
                                "id": call_id,
                                "name": tool_name
                            })

                        assistant_msg = {
                            "role": "assistant",
                            "content": content.strip() if content else "",
                            "tool_calls": formatted_tool_calls
                        }
                        if thinking:
                            assistant_msg["thinking"] = thinking
                        trajectory_messages.append(assistant_msg)

                    else:
                        # Conversational final reply
                        msg_obj = {
                            "role": "assistant",
                            "content": content.strip() if content else ""
                        }
                        if thinking:
                            msg_obj["thinking"] = thinking

                        chat_messages.append(msg_obj)
                        trajectory_messages.append(msg_obj)
                        active_tool_calls = []

                # 3. ENVIRONMENT TOOL OUTPUTS (File Content, Command Result, etc.)
                elif step_type not in ["USER_INPUT", "PLANNER_RESPONSE"] and source != "USER_EXPLICIT" and source != "MODEL":
                    # This is the output of a tool call
                    tool_name = step_type.lower()

                    # Try to match it with one of our active tool calls
                    matching_call = None
                    for tc in active_tool_calls:
                        if tc["name"].lower() == tool_name:
                            matching_call = tc
                            active_tool_calls.remove(tc)
                            break

                    call_id = matching_call["id"] if matching_call else f"call_orphaned_{step_index}"
                    t_name = matching_call["name"] if matching_call else tool_name

                    trajectory_messages.append({
                        "role": "tool",
                        "tool_call_id": call_id,
                        "name": t_name,
                        "content": content.strip() if content else ""
                    })

            except Exception as e:
                continue

    # Structure datasets
    chat_dataset = [
        {
            "conversation_id": "9886e02d-2736-4e97-8bb3-121ab47042e8",
            "messages": chat_messages
        }
    ]

    trajectory_dataset = [
        {
            "conversation_id": "9886e02d-2736-4e97-8bb3-121ab47042e8",
            "messages": trajectory_messages
        }
    ]

    # Save files
    with open(chat_output_path, 'w', encoding='utf-8') as out_f:
        json.dump(chat_dataset, out_f, ensure_ascii=False, indent=2)

    with open(trajectory_output_path, 'w', encoding='utf-8') as out_f:
        json.dump(trajectory_dataset, out_f, ensure_ascii=False, indent=2)

    print(f"Chat dataset: {chat_output_path} ({len(chat_messages)} turns)")
    print(f"Agent trajectory dataset: {trajectory_output_path} ({len(trajectory_messages)} turns)")
    print("Agent trajectory contains full file inputs (contents of files viewed) and command outputs!")

if __name__ == "__main__":
    main()
